package com.example.fulfillmentservice.config;import io.swagger.v3.oas.models.OpenAPI;import io.swagger.v3.oas.models.info.Info;import org.springframework.context.annotation.*;import org.springframework.web.servlet.config.annotation.*;@Configuration public class Config implements WebMvcConfigurer{@Bean OpenAPI api(){return new OpenAPI().info(new Info().title("Fulfillment API").version("1.0.0").description("Asynchronous phone delivery lifecycle."));}public void addCorsMappings(CorsRegistry r){r.addMapping("/api/**").allowedOrigins("http://localhost:5173","http://localhost:5174").allowedMethods("*");}}
